CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS matches (id TEXT PRIMARY KEY, match_info_id INTEGER NOT NULL, stage_id INTEGER NOT NULL, stage_name TEXT NOT NULL, group_name TEXT, china_date TEXT NOT NULL, china_time TEXT NOT NULL, china_datetime TEXT NOT NULL, kickoff_ms INTEGER NOT NULL, home_team TEXT, away_team TEXT, venue TEXT, match_status INTEGER NOT NULL DEFAULT 1, football_live_score TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS predictions (match_id TEXT NOT NULL, user_id TEXT NOT NULL, pick TEXT NOT NULL, pick_label TEXT NOT NULL, stake_amount REAL NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY (match_id, user_id), FOREIGN KEY (match_id) REFERENCES matches(id), FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS settlements (match_id TEXT PRIMARY KEY, settled_at TEXT NOT NULL, china_date TEXT NOT NULL, result TEXT, result_label TEXT, stake_amount REAL NOT NULL, score_text TEXT, status TEXT NOT NULL, void_reason TEXT, entries TEXT NOT NULL, FOREIGN KEY (match_id) REFERENCES matches(id));
CREATE INDEX IF NOT EXISTS idx_matches_china_date ON matches(china_date);
CREATE INDEX IF NOT EXISTS idx_matches_kickoff ON matches(kickoff_ms);
CREATE INDEX IF NOT EXISTS idx_predictions_user ON predictions(user_id);
CREATE INDEX IF NOT EXISTS idx_settlements_china_date ON settlements(china_date);
